mapper.select:
SELECT sym.id, sym.paper_id AS paperId, sym.symbol, sym.description, sym.definition_formula AS definitionFormula, p.title AS sourcePaperTitle, 1 - (sym.embedding <=> cast(#{vectorStr} as vector)) AS score FROM paper_symbols sym LEFT JOIN papers p ON sym.paper_id = p.id WHERE sym.embedding IS NOT NULL
AND sym.paper_id = #{paperId}
ORDER BY sym.embedding <=> cast(#{vectorStr} as vector) LIMIT #{topK}
